code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The full line of 2s is the fixed wall; the other objects slide toward it.
    wall = None
    for r, row in enumerate(g):
        if all(v == 2 for v in row):
            wall = ("up", r)
            break
    if wall is None:
        for c in range(w):
            if all(g[r][c] == 2 for r in range(h)):
                wall = ("left", c)
                break
    if wall is None:
        return g
    direction, line = wall
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                rr, cc = stack.pop()
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and g[nr][nc] == color:
                        seen.add((nr,nc)); cells.add((nr,nc)); stack.append((nr,nc))
            objects.append((color, cells))
    # Move rigid same-color components one cell at a time until they settle.
    changed = True
    while changed:
        changed = False
        occupied = {(r,c) for r in range(h) for c in range(w) if g[r][c] != 0}
        # Components closest to the wall move first; repeat to settle components behind them.
        def distance(obj):
            cells = obj[1]
            return min(r for r,c in cells) if direction == "up" else min(c for r,c in cells)
        for color, cells in sorted(objects, key=distance):
            dr, dc = (-1,0) if direction == "up" else (0,-1)
            targets = {(r+dr,c+dc) for r,c in cells}
            # Ignore the component's own current cells when checking a one-cell move.
            if any(not (0 <= r < h and 0 <= c < w) or (g[r][c] != 0 and (r,c) not in cells) for r,c in targets):
                continue
            for r,c in cells:
                g[r][c] = 0
            moved = {(r+dr,c+dc) for r,c in cells}
            for r,c in moved:
                g[r][c] = color
            cells.clear(); cells.update(moved)
            changed = True
    return g
'''
